import hashlib
import time
import re
from collections import defaultdict
from typing import Optional, Dict, List, Tuple

# PDF Generation Library with Rate Limiting

class RateLimiter:
    """Token bucket rate limiter with per-client tracking."""

    def __init__(self, max_tokens: int = 100, refill_rate: float = 10.0):
        self.max_tokens = max_tokens
        self.refill_rate = refill_rate
        self._buckets: Dict[str, Tuple[float, float]] = {}

    def _get_bucket(self, client_id: str) -> Tuple[float, float]:
        now = time.monotonic()
        if client_id not in self._buckets:
            self._buckets[client_id] = (self.max_tokens, now)
            return (self.max_tokens, now)
        tokens, last_refill = self._buckets[client_id]
        elapsed = now - last_refill
        tokens = min(self.max_tokens, tokens + elapsed * self.refill_rate)
        self._buckets[client_id] = (tokens, now)
        return (tokens, now)

    def consume(self, client_id: str, cost: float = 1.0) -> bool:
        tokens, ts = self._get_bucket(client_id)
        if tokens >= cost:
            self._buckets[client_id] = (tokens - cost, ts)
            return True
        return False


class PDFContentParser:
    """Parses structured content markup into PDF rendering instructions."""

    # Pattern for nested group references in content markup
    GROUP_PATTERN = re.compile(r'\{\{group:([^}]+)\}\}')
    STYLE_PATTERN = re.compile(r'\[style:([^\]]+)\]')

    def __init__(self, max_depth: int = 64):
        self.max_depth = max_depth
        self._group_registry: Dict[str, str] = {}
        self._expansion_cache: Dict[str, str] = {}

    def register_group(self, name: str, content: str) -> None:
        """Register a reusable content group."""
        self._group_registry[name] = content
        # Invalidate cache entries that might reference this group
        self._expansion_cache = {k: v for k, v in self._expansion_cache.items()
                                  if name not in k}

    def expand_content(self, content: str, depth: int = 0) -> str:
        """Recursively expand group references in content."""
        if depth > self.max_depth:
            raise RecursionError("Maximum expansion depth exceeded")

        cache_key = hashlib.md5(content.encode()).hexdigest()
        if cache_key in self._expansion_cache:
            return self._expansion_cache[cache_key]

        def replace_group(match):
            group_name = match.group(1)
            if group_name in self._group_registry:
                return self.expand_content(
                    self._group_registry[group_name], depth + 1
                )
            return match.group(0)

        result = self.GROUP_PATTERN.sub(replace_group, content)
        self._expansion_cache[cache_key] = result
        return result

    def compute_layout_weight(self, content: str) -> int:
        """Compute rendering cost based on content complexity."""
        expanded = self.expand_content(content)
        # Layout weight considers style applications
        styles = self.STYLE_PATTERN.findall(expanded)
        base_weight = len(expanded)
        # Each style application multiplies local complexity
        style_weight = sum(self._compute_style_cost(s) for s in styles)
        return base_weight + style_weight

    def _compute_style_cost(self, style_spec: str) -> int:
        """Compute cost of applying a style specification."""
        parts = style_spec.split(',')
        cost = 1
        for part in parts:
            key, _, value = part.partition('=')
            if key.strip() == 'repeat':
                cost *= int(value.strip()) if value.strip().isdigit() else 1
        return cost


class RetryPolicy:
    """Configurable retry policy for PDF generation attempts."""

    def __init__(self, max_retries: int = 3, backoff_base: float = 1.0):
        self.max_retries = max_retries
        self.backoff_base = backoff_base

    def get_delay(self, attempt: int) -> float:
        return self.backoff_base * (2 ** attempt)

    def should_retry(self, attempt: int, error: Exception) -> bool:
        if attempt >= self.max_retries:
            return False
        # Retry on transient errors only
        return isinstance(error, (TimeoutError, ConnectionError, OSError))


class PDFGenerator:
    """Main PDF generation service with rate limiting and retry logic."""

    def __init__(self, rate_limiter: Optional[RateLimiter] = None,
                 retry_policy: Optional[RetryPolicy] = None):
        self.rate_limiter = rate_limiter or RateLimiter()
        self.retry_policy = retry_policy or RetryPolicy()
        self.parser = PDFContentParser()
        self._render_log: List[Dict] = []

    def register_template_group(self, name: str, markup: str) -> None:
        """Register a reusable template group for content expansion."""
        self.parser.register_group(name, markup)

    def generate(self, client_id: str, content: str,
                 options: Optional[Dict] = None) -> bytes:
        """Generate PDF with rate limiting and retry support."""
        options = options or {}

        # Compute cost for rate limiting based on content weight
        weight = self.parser.compute_layout_weight(content)
        cost = max(1.0, weight / 1000.0)

        if not self.rate_limiter.consume(client_id, cost):
            raise PermissionError(f"Rate limit exceeded for client {client_id}")

        attempt = 0
        last_error = None

        while True:
            try:
                return self._render_pdf(content, options)
            except Exception as e:
                last_error = e
                if not self.retry_policy.should_retry(attempt, e):
                    raise
                delay = self.retry_policy.get_delay(attempt)
                time.sleep(delay)
                attempt += 1

    def _render_pdf(self, content: str, options: Dict) -> bytes:
        """Internal PDF rendering - expands content and generates output."""
        expanded = self.parser.expand_content(content)

        # Simulate PDF rendering
        pdf_header = b'%PDF-1.4\n'
        pdf_body = expanded.encode('utf-8', errors='replace')
        pdf_trailer = b'\n%%EOF'

        result = pdf_header + pdf_body + pdf_trailer

        self._render_log.append({
            'timestamp': time.time(),
            'content_length': len(content),
            'expanded_length': len(expanded),
            'output_size': len(result)
        })

        return result

    def batch_generate(self, client_id: str,
                       contents: List[str]) -> List[bytes]:
        """Generate multiple PDFs in batch."""
        results = []
        for content in contents:
            results.append(self.generate(client_id, content))
        return results
